package com.naivety.zhicolor.bridge;
import org.junit.Test;import static org.junit.Assert.*;import java.nio.file.*;import java.util.*;
public final class ZhiColorSettingsContractTest {
 @Test public void defaultAppearanceExactlyMatchesSoft(){LyricUiConfig c=LyricUiPreset.SOFT.apply(LyricUiConfig.defaults());assertEquals(36,c.inactiveOpacityPercent);assertEquals(20,c.blurRadiusTenthsPx);assertEquals(96,c.inactiveScalePercent);assertEquals(60,c.glowIntensityPercent);assertEquals(14,c.glowRadiusPercent);assertEquals(LyricUiConfig.MOTION_REDUCED,c.motionMode);assertEquals("#FFFFFF",c.primaryColor);assertEquals("#FFD68A",c.glowColor);}
 @Test public void uiCoversEveryPersistedVisualField()throws Exception{String ui=Files.readString(Path.of("../app/src/main/java/com/naivety/zhicolor/ui/screen/BridgeUiComponents.kt"));for(String key:LyricUiConfigCodec.encode(LyricUiConfig.defaults()).keySet())if(!key.equals(LyricUiConfigCodec.SCHEMA)&&!key.equals(LyricUiConfigCodec.GLOW_ENABLED))assertTrue("Missing control "+key,ui.contains("\""+key+"\""));}
 @Test public void uiUsesNativeMiuixAndNoPresetSelector()throws Exception{String ui=Files.readString(Path.of("../app/src/main/java/com/naivety/zhicolor/ui/screen/LyricsScreen.kt"));assertTrue(ui.contains("top.yukonga.miuix.kmp.basic"));assertFalse(ui.contains("风格预设"));assertFalse(ui.contains("LyricUiSettingsActivity"));}
 @Test public void backupDelegatesToOriginalCodecAndRepository()throws Exception{String facade=Files.readString(Path.of("src/main/java/com/naivety/zhicolor/bridge/BridgeSettings.java"));assertTrue(facade.contains("BridgeConfigBackupRepository.exportAll"));assertTrue(facade.contains("BridgeConfigBackupRepository.restoreAll"));assertTrue(facade.contains("BridgeConfigBackupCodec.decode"));}
 @Test public void foreignProviderReceiverWasRemoved(){assertFalse(Files.exists(Path.of("src/main/java/com/naivety/zhicolor/bridge/UniversalPlayerBindingsReceiver.java")));}
 @Test public void settingsPushFullSnapshotAndKeepSignatureGate()throws Exception{String settings=Files.readString(Path.of("src/main/java/com/naivety/zhicolor/bridge/BridgeSettings.java"));String runtime=Files.readString(Path.of("src/main/java/com/naivety/zhicolor/bridge/ZhiBridgeRuntime.java"));assertTrue(settings.contains("putExtra(EXTRA_SNAPSHOT,snapshot)"));assertTrue(runtime.contains("getBundleExtra(BridgeSettings.EXTRA_SNAPSHOT)"));assertTrue(runtime.contains("registerReceiver(receiver,filter,BridgeSettings.PERMISSION"));assertTrue(runtime.contains("BridgeSettings.cachedSnapshot(context)"));}
 @Test public void remoteCallbacksUseFrameworkParcelableType()throws Exception{String settings=Files.readString(Path.of("src/main/java/com/naivety/zhicolor/bridge/BridgeSettings.java"));assertTrue(settings.contains("ResultReceiver.CREATOR.createFromParcel(parcel)"));assertEquals(2,settings.split("EXTRA_RESULT_RECEIVER,remoteReceiver",-1).length-1);}
}
